"""MPRA-LegNet (Penzar et al. 2023; human_legnet), with one output per cell type."""
import torch
from torch import nn
import torch.nn.functional as F


# EVOLVE-BLOCK-START name=model kind=structure
class SELayer(nn.Module):
    def __init__(self, inp, oup, reduction=4):
        super().__init__()
        self.fc = nn.Sequential(
            nn.Linear(oup, inp // reduction), nn.SiLU(),
            nn.Linear(inp // reduction, oup), nn.Sigmoid())

    def forward(self, x):
        y = self.fc(x.mean(dim=2))
        return x * y.unsqueeze(-1)


class EffBlock(nn.Module):
    def __init__(self, in_ch, ks, resize_factor, activation):
        super().__init__()
        mid = in_ch * resize_factor
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, mid, 1, bias=False), nn.BatchNorm1d(mid), activation(),
            nn.Conv1d(mid, mid, ks, groups=mid, padding="same", bias=False), nn.BatchNorm1d(mid), activation(),
            SELayer(in_ch, mid, reduction=4),
            nn.Conv1d(mid, in_ch, 1, bias=False), nn.BatchNorm1d(in_ch), activation())

    def forward(self, x):
        return self.block(x)


class LocalBlock(nn.Module):
    def __init__(self, in_ch, out_ch, ks, activation):
        super().__init__()
        self.block = nn.Sequential(
            nn.Conv1d(in_ch, out_ch, ks, padding="same", bias=False), nn.BatchNorm1d(out_ch), activation())

    def forward(self, x):
        return self.block(x)


class ResidualConcat(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x):
        return torch.cat([self.fn(x), x], dim=1)


class LegNet(nn.Module):
    def __init__(self, n_outputs=3, in_ch=4, stem_ch=64, stem_ks=11, ef_ks=9,
                 ef_block_sizes=(80, 96, 112, 128), pool_sizes=(2, 2, 2, 2), resize_factor=4,
                 activation=nn.SiLU):
        super().__init__()
        self.stem = LocalBlock(in_ch, stem_ch, stem_ks, activation)
        blocks = []
        ch = stem_ch
        for pool, out_ch in zip(pool_sizes, ef_block_sizes):
            blocks.append(nn.Sequential(
                ResidualConcat(EffBlock(ch, ef_ks, resize_factor, activation)),
                LocalBlock(ch * 2, out_ch, ef_ks, activation),
                nn.MaxPool1d(pool) if pool != 1 else nn.Identity()))
            ch = out_ch
        self.main = nn.Sequential(*blocks)
        self.mapper = nn.Sequential(nn.Conv1d(ch, ch * 2, 1, bias=False), nn.BatchNorm1d(ch * 2), activation())
        self.head = nn.Sequential(
            nn.Linear(ch * 2, ch * 2), nn.BatchNorm1d(ch * 2), activation(),
            nn.Linear(ch * 2, n_outputs))

    def forward(self, x):
        x = self.mapper(self.main(self.stem(x)))
        return self.head(F.adaptive_avg_pool1d(x, 1).squeeze(-1))


def build_model(n_outputs=3):
    return LegNet(n_outputs=n_outputs)
# EVOLVE-BLOCK-END

"""Malinois (Gosai et al. 2024): boda2's BassetBranched with the published hyperparameters, and its L1KLmixed
loss. Parameter names match boda2's state dicts, so the published checkpoint and the Basset parent load as is.

conv 300x19 -> BN -> ReLU -> maxpool 3; conv 200x11 -> BN -> ReLU -> maxpool 4; conv 200x7 -> BN -> ReLU ->
pad 1 -> maxpool 4 (same padding throughout); flatten (200 x 13 for 600 bp); linear 1000 -> BN -> ReLU ->
dropout 0.116; three grouped (one per cell type) linear layers of 140 with ReLU and dropout 0.576 between;
one output per cell type.
"""
import math
import torch
import torch.nn as nn
import torch.nn.functional as F


class ConvNorm(nn.Module):
    def __init__(self, cin, cout, k):
        super().__init__()
        self.conv = nn.Conv1d(cin, cout, k)
        self.bn_layer = nn.BatchNorm1d(cout)
        self.pad = ((k - 1) // 2, k - 1 - (k - 1) // 2)

    def forward(self, x):
        return self.bn_layer(self.conv(F.pad(x, self.pad)))


class LinearNorm(nn.Module):
    def __init__(self, cin, cout):
        super().__init__()
        self.linear = nn.Linear(cin, cout)
        self.bn_layer = nn.BatchNorm1d(cout)

    def forward(self, x):
        return self.bn_layer(self.linear(x))


class GroupedLinear(nn.Module):
    """One independent linear map per group: (B, groups * cin) -> (B, groups * cout)."""

    def __init__(self, cin, cout, groups):
        super().__init__()
        self.cin, self.cout, self.groups = cin, cout, groups
        self.weight = nn.Parameter(torch.zeros(groups, cin, cout))
        self.bias = nn.Parameter(torch.zeros(groups, 1, cout))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(3))
        bound = 1 / math.sqrt(nn.init._calculate_fan_in_and_fan_out(self.weight)[0])
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        h = x.permute(1, 0).reshape(self.groups, self.cin, -1).permute(0, 2, 1)
        h = torch.bmm(h, self.weight) + self.bias
        return h.permute(0, 2, 1).reshape(self.cout * self.groups, -1).permute(1, 0)


class Branched(nn.Module):
    def __init__(self, cin, hidden, n_branches, n_layers, dropout):
        super().__init__()
        self.n_branches, self.n_layers = n_branches, n_layers
        self.dropout = nn.Dropout(dropout)
        size = cin
        for i in range(n_layers):
            setattr(self, f"branched_layer_{i + 1}", GroupedLinear(size, hidden, n_branches))
            size = hidden

    def forward(self, x):
        h = x.repeat(1, self.n_branches)
        for i in range(self.n_layers - 1):
            h = self.dropout(F.relu(getattr(self, f"branched_layer_{i + 1}")(h)))
        return getattr(self, f"branched_layer_{self.n_layers}")(h)


class Malinois(nn.Module):
    def __init__(self, input_len=600, n_outputs=3, linear_dropout=0.11625456877954289,
                 branched_dropout=0.5757068086404574):
        super().__init__()
        self.conv1 = ConvNorm(4, 300, 19)
        self.conv2 = ConvNorm(300, 200, 11)
        self.conv3 = ConvNorm(200, 200, 7)
        flat = ((input_len // 3 // 4) + 2) // 4
        self.linear1 = LinearNorm(200 * flat, 1000)
        self.dropout = nn.Dropout(linear_dropout)
        self.branched = Branched(1000, 140, n_outputs, 3, branched_dropout)
        self.output = GroupedLinear(140, 1, n_outputs)

    def forward(self, x):
        """x: one-hot (B, 4, 600)."""
        h = F.max_pool1d(F.relu(self.conv1(x)), 3)
        h = F.max_pool1d(F.relu(self.conv2(h)), 4)
        h = F.max_pool1d(F.pad(F.relu(self.conv3(h)), (1, 1)), 4)
        h = self.dropout(F.relu(self.linear1(h.flatten(1))))
        return self.output(self.branched(h))


def l1_kl_mixed(pred, target, alpha=1.0, beta=5.0):
    """boda2 L1KLmixed (reduction 'mean'): L1 plus KL between the softmaxes over cell types, averaged over
    all elements, (alpha * L1 + beta * KL) / (alpha + beta)."""
    lp = pred - torch.logsumexp(pred, -1, keepdim=True)
    lt = target - torch.logsumexp(target, -1, keepdim=True)
    kl = F.kl_div(lp, lt, reduction="mean", log_target=True)
    return (alpha * F.l1_loss(pred, target) + beta * kl) / (alpha + beta)


def build_model():
    """Malinois with the published hyperparameters: (B, 4, 600) one-hot -> (B, 3)."""
    return Malinois()

